import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import styles from './ai-disclaimer.module.css'

export interface AiDisclaimerProps extends HTMLAttributes<HTMLParagraphElement> {
  labels?: {
    text?: string
  }
}

export function AiDisclaimer({ labels, className, children, ...props }: AiDisclaimerProps) {
  return (
    <p className={cn(styles['disclaimer'], className as string | undefined)} {...props}>
      <svg
        className={styles['glyph']}
        viewBox="0 0 16 16"
        width="12"
        height="12"
        fill="currentColor"
        aria-hidden="true"
      >
        <path d="M8 1c.6 3.9 3.1 6.4 7 7-3.9.6-6.4 3.1-7 7-.6-3.9-3.1-6.4-7-7 3.9-.6 6.4-3.1 7-7Z" />
      </svg>
      <span>{children ?? labels?.text ?? t(builtin.aiDisclaimer.text)}</span>
    </p>
  )
}

@layer cascivo.component {
  .disclaimer {
    display: flex;
    align-items: baseline;
    gap: var(--cascivo-space-1);
    margin: 0;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    line-height: var(--cascivo-leading-snug);
    color: var(--cascivo-color-text-muted);
  }

  .glyph {
    flex: none;
    color: var(--cascivo-color-ai);
    translate: 0 0.0625rem;
  }
}

@media (forced-colors: active) {
  .glyph {
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'AiDisclaimer',
  description:
    'A short, quiet note that AI-generated content may be wrong — "AI-generated content may be incorrect"',
  category: 'feedback',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'children',
      description: 'Replaces the default text — e.g. naming the model or what to double-check.',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ text?: string }',
      required: false,
    },
  ],
  tokens: ['--cascivo-color-text-muted', '--cascivo-color-ai', '--cascivo-text-xs'],
  accessibility: { role: 'paragraph', wcag: '2.2-AA', keyboard: [], forcedColors: true },
  examples: [
    { title: 'Default', code: '<AiDisclaimer />' },
    {
      title: 'Specific',
      code: '<AiDisclaimer>Summaries are generated by AI. Check figures against the source report.</AiDisclaimer>',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['ai', 'disclaimer', 'disclosure', 'notice', 'provenance', 'generated'],
  intent: {
    whenToUse: [
      'Under an AI chat composer or answer, telling readers the output can be wrong',
      'Beside AI-generated summaries, drafts or suggestions that people may act on',
    ],
    whenNotToUse: [
      'Marking a single field or card as AI-generated — use AiBadge',
      'Warnings the reader must act on — use Alert',
    ],
    antiPatterns: [
      {
        bad: 'Repeating the disclaimer under every message in a conversation',
        good: 'Show it once, under the composer or at the end of the thread',
        why: 'Repeated boilerplate is skimmed past and stops being read',
      },
    ],
    related: [
      {
        name: 'AiBadge',
        relationship: 'pairs-with',
        reason: 'AiBadge marks which content is AI-generated; the disclaimer says what that means',
      },
      {
        name: 'Alert',
        relationship: 'alternative',
        reason: 'Alert is for messages that need attention or action',
      },
    ],
    a11yRationale:
      'A plain paragraph: read in document order, never a live region, because it is static guidance rather than a status change. The sparkle is aria-hidden; muted text keeps AA contrast on every theme',
    content: {
      tone: 'Plain and specific — say what may be wrong and what to check',
      notes: 'One sentence; avoid legalese',
    },
    flexibility: [
      { area: 'text', level: 'flexible', note: 'Replace via children or labels.text' },
      {
        area: 'placement',
        level: 'flexible',
        note: 'Typically under a composer or at the foot of AI content',
      },
    ],
  },
}
